#!/usr/bin/env node
// The home page's CSS and JS are cacheable files under public/assets (a year, immutable, vercel.json), each loaded
// from data/pages/index.html with ?v=<content hash> so a change is picked up at once:
//   assets/app.css   the page's styles (with the self-hosted Geist @font-face rules, assets/fonts)
//   assets/lib.js    LIBS (breaking, routes, featured, adslots, adsizes, flowers, eventtime, dedupe, crime) in that order, then the call that
//                    points the head at the current tab; built from those files, which stay in public/ for the other
//                    pages and the tests. Loaded with defer in <head>, before app.js.
//   assets/app.js    the page script, defer in <head> (runs after the document is parsed, as at the end of <body>)
//   assets/speed-insights.js  the official @vercel/speed-insights injector (node_modules, the version pinned in
//                    package.json) wrapped as a plain script, then public/speed-insights.js; defer, on SI_PAGES only
// Run after editing any of them:  node scripts/build-assets.js   (test/assets.test.js fails when lib.js or a hash is
// stale). Run against an index.html that still has the inline <style>/<script> blocks, it moves them out first.
'use strict';
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const PUB = path.join(__dirname, '..', 'public');
const INDEX = path.join(__dirname, '..', 'data', 'pages', 'index.html');
const CSS = path.join(PUB, 'assets', 'app.css');
const JS = path.join(PUB, 'assets', 'app.js');
const LIB = path.join(PUB, 'assets', 'lib.js');
const LIBS = ['breaking.js', 'routes.js', 'featured.js', 'adslots.js', 'adsizes.js', 'flowers.js', 'eventtime.js', 'dedupe.js', 'crime.js', 'obit.js', 'tragedy.js', 'utility.js', 'cluster.js'];
const APPLY = '/* each tab has its own URL: set this one\'s title, description and canonical first */ if (window.TSNRoutes) TSNRoutes.apply(document, TSNRoutes.byPath(location.pathname));';

const hash = s => crypto.createHash('sha256').update(s).digest('hex').slice(0, 10);
const cssTag = v => '<link rel="stylesheet" href="/assets/app.css?v=' + v + '">';
const jsTag = v => '<script defer src="/assets/app.js?v=' + v + '"></script>';
const libTag = v => '<script defer src="/assets/lib.js?v=' + v + '"></script>';
const SI = path.join(PUB, 'assets', 'speed-insights.js');
const SI_PKG = path.join(__dirname, '..', 'node_modules', '@vercel', 'speed-insights');
const SI_PAGES = [INDEX, path.join(PUB, 'legal.html'), path.join(PUB, 'newsletter.html'), path.join(__dirname, '..', 'data', 'pages', 'advertise.html')];
const siTag = v => '<script defer src="/assets/speed-insights.js?v=' + v + '"></script>';
const SI_TAG = /<script defer src="\/assets\/speed-insights\.js\?v=[^"]*"><\/script>/;
function siSource() {
  const pkg = JSON.parse(fs.readFileSync(path.join(SI_PKG, 'package.json'), 'utf8'));
  const cjs = fs.readFileSync(path.join(SI_PKG, 'dist', 'index.js'), 'utf8').replace(/\n\/\/# sourceMappingURL=\S+\s*$/, '\n');
  return '/* ' + pkg.name + ' ' + pkg.version + ' (dist/index.js, ' + pkg.license + ', https://github.com/vercel/speed-insights),'
    + ' generated by scripts/build-assets.js; then public/speed-insights.js */\n'
    + '(function () {\nvar module = { exports: {} }, exports = module.exports;\n' + cjs.replace(/\s*$/, '\n')
    + 'window.TSNSpeedInsights = module.exports;\n})();\n'
    + fs.readFileSync(path.join(PUB, 'speed-insights.js'), 'utf8');
}
const libSource = () => LIBS.map(f => '/* ---- public/' + f + ' ---- */\n' + fs.readFileSync(path.join(PUB, f), 'utf8').replace(/\s*$/, '\n')).join(';\n') + ';\n' + APPLY + '\n';

function build() {
  let html = fs.readFileSync(INDEX, 'utf8');
  const style = /\n<style>\n([\s\S]*?)<\/style>\n<\/head>/.exec(html);
  if (style) { fs.mkdirSync(path.dirname(CSS), { recursive: true }); fs.writeFileSync(CSS, style[1]); html = html.replace(style[0], '\n' + cssTag('x') + '\n</head>'); }
  const script = /\n<script>\n(\(function \(\) \{[\s\S]*?)<\/script>\n<\/body>/.exec(html);
  if (script) { fs.writeFileSync(JS, script[1]); html = html.replace(script[0], '\n</body>').replace('</head>', jsTag('x') + '\n</head>'); }
  fs.writeFileSync(LIB, libSource());
  html = html.replace(/<link rel="stylesheet" href="\/assets\/app\.css\?v=[^"]*">/, cssTag(hash(fs.readFileSync(CSS, 'utf8'))))
    .replace(/<script defer src="\/assets\/lib\.js\?v=[^"]*"><\/script>/, libTag(hash(fs.readFileSync(LIB, 'utf8'))))
    .replace(/<script defer src="\/assets\/app\.js\?v=[^"]*"><\/script>/, jsTag(hash(fs.readFileSync(JS, 'utf8'))));
  fs.writeFileSync(INDEX, html);
  fs.writeFileSync(SI, siSource());
  const v = hash(fs.readFileSync(SI, 'utf8'));
  for (const f of SI_PAGES) {
    const page = fs.readFileSync(f, 'utf8');
    if (!SI_TAG.test(page)) throw new Error(path.relative(process.cwd(), f) + ' has no speed-insights.js tag');
    fs.writeFileSync(f, page.replace(SI_TAG, siTag(v)));
  }
}

if (require.main === module) build();
module.exports = { build, hash, cssTag, jsTag, libTag, siTag, libSource, siSource, LIBS, APPLY, INDEX, CSS, JS, SI, SI_PAGES };
